using namespace std;

int N, M, Q, p, r, a;
int prv[200007], nxt[200007];

int main() {
    scanf("%d %d %d", &N, &M, &Q);

    // Initialize prv and nxt using a single loop
    for (int i = 0; i < N; i++) {
        prv[i] = (i - 1 + N) % N; // Adjusted to directly calculate previous index
        nxt[i] = (i + 1) % N;      // Directly calculate next index
    }

    // Use a single loop for processing M queries
    while (M--) {
        scanf("%d", &a);
        for (int j = 0; j < a; j++) {
            p = (a % 2) ? prv[p] : nxt[p];
        }

        // Directly unlink p from the list
        nxt[prv[p]] = nxt[p];
        prv[nxt[p]] = prv[p];

        r = nxt[p];
        prv[p] = nxt[p] = -1;
        p = r;
    }

    // Output results for Q queries
    while (Q--) {
        scanf("%d", &a);
        printf("%d\n", (prv[a] != -1 ? 1 : 0));
    }

    return 0;
}

